import katex from "katex";

/**
 * Renders TeX extracted from Wikipedia's <math alttext> into KaTeX HTML.
 * KaTeX output is generated by us from TeX source with `trust: false`, so it
 * cannot carry arbitrary markup from the source page. If KaTeX cannot handle
 * an expression we return no HTML and the UI shows the TeX source instead.
 */

// Macros from MediaWiki's texvc dialect that KaTeX does not define natively.
const TEXVC_MACROS: Record<string, string> = {
  "\\R": "\\mathbb{R}",
  "\\Reals": "\\mathbb{R}",
  "\\reals": "\\mathbb{R}",
  "\\N": "\\mathbb{N}",
  "\\natnums": "\\mathbb{N}",
  "\\Z": "\\mathbb{Z}",
  "\\Q": "\\mathbb{Q}",
  "\\C": "\\mathbb{C}",
  "\\Complex": "\\mathbb{C}",
  "\\H": "\\mathbb{H}",
  "\\sgn": "\\operatorname{sgn}",
  "\\and": "\\land",
  "\\or": "\\lor",
  "\\empty": "\\emptyset",
  "\\infin": "\\infty",
  "\\isin": "\\in",
  "\\part": "\\partial",
  "\\plusmn": "\\pm",
  "\\sub": "\\subset",
  "\\sube": "\\subseteq",
  "\\supe": "\\supseteq",
  "\\lang": "\\langle",
  "\\rang": "\\rangle",
  "\\real": "\\Re",
  "\\image": "\\Im",
  "\\alef": "\\aleph",
  "\\alefsym": "\\aleph",
  "\\larr": "\\leftarrow",
  "\\rarr": "\\rightarrow",
  "\\Larr": "\\Leftarrow",
  "\\Rarr": "\\Rightarrow",
  "\\harr": "\\leftrightarrow",
  "\\Harr": "\\Leftrightarrow",
  "\\uarr": "\\uparrow",
  "\\darr": "\\downarrow",
  "\\bull": "\\bullet",
  "\\exist": "\\exists",
  "\\thetasym": "\\vartheta",
  "\\weierp": "\\wp",
  "\\O": "\\emptyset",
  "\\Dagger": "\\ddagger",
  "\\arccot": "\\operatorname{arccot}",
  "\\arcsec": "\\operatorname{arcsec}",
  "\\arccsc": "\\operatorname{arccsc}",
  "\\sen": "\\operatorname{sen}",
};

/** Strips Wikipedia's `{\displaystyle …}` / `{\textstyle …}` wrappers. */
export function unwrapTex(raw: string): string {
  const trimmed = raw.trim();
  const match = /^\{\\(?:displaystyle|textstyle)\s*([\s\S]*)\}$/.exec(trimmed);
  return (match?.[1] ?? trimmed).trim();
}

const memo = new Map<string, string | null>();

export function renderTex(raw: string, display: boolean): { tex: string; html?: string } {
  const tex = unwrapTex(raw);
  const key = `${display ? "D" : "I"}:${tex}`;
  let html = memo.get(key);
  if (html === undefined) {
    try {
      html = katex.renderToString(tex, {
        displayMode: display,
        throwOnError: true,
        strict: "ignore",
        trust: false,
        output: "htmlAndMathml",
        macros: { ...TEXVC_MACROS },
        maxExpand: 1000,
        maxSize: 50,
      });
    } catch {
      html = null;
    }
    if (memo.size > 20000) memo.clear();
    memo.set(key, html);
  }
  return html ? { tex, html } : { tex };
}
